entry.css:
/* 整个窗子由自己画：圆角、阴影、配色都在这里定 */
html,body{height:100%}
#win{height:100%;display:flex;flex-direction:column;overflow:hidden;
     border-radius:18px;color:#fff;
     background:linear-gradient(160deg,#5b4bff,#c04bff);
     box-shadow:0 10px 30px rgba(80,40,200,.45)}
#bar{display:flex;align-items:center;gap:8px;padding:10px 12px;
     font-size:13px;font-weight:700;cursor:grab}
#title{flex:1}
#close{background:rgba(255,255,255,.25);border:none;color:#fff;
       width:20px;height:20px;border-radius:50%;cursor:pointer;line-height:1}
#body{flex:1;display:flex;align-items:center;justify-content:center;
      font-size:12px;opacity:.9;padding:10px;text-align:center}

entry.js:
// 自画窗口模板
//
// 宿主只做三件事：把窗放在记住的位置、转发拖拽位移、在你要求时关掉窗。
// 其余（标题栏长什么样、有没有最小化、圆角多大）全是你自己的事。

// 把标题栏变成拖拽把手（里面的 button 不会触发拖拽）
nuo.window.dragHandle(document.getElementById('bar'));

document.getElementById('close').addEventListener('click', function () {
  nuo.window.close();
});

// 想变大变小自己说了算（受槽位上限约束）
// nuo.window.resize(300, 200);

nuo.ready();
